package dev.zomboid.firstaid;
import java.util.*;import net.minecraft.world.entity.player.Player;
public class AssistChecks {
 static int n;static void check(boolean v){n++;if(!v)throw new AssertionError(n);}
 public static class World {public boolean client;public long clock;public int sounds;public void playSound(Object p,Object pos,Object sound,Object source,float volume,float pitch){sounds++;}public boolean isClientSide(){return client;}public long getGameTime(){return clock;}}
 public static class Stack {public boolean defib;public int uses;public void hurtAndBreak(int n,Object p,Object slot){uses+=n;}}
 public static class Attribute {public Map<Object,Object> values=new HashMap<>();public Object getModifier(Object id){return values.get(id);}public void addPermanentModifier(net.minecraft.world.entity.ai.attributes.AttributeModifier modifier){values.put(modifier.id(),modifier);}}
 public static class Tag {Map<String,Object> data=new HashMap<>();public void putInt(String k,int v){data.put(k,v);}public int getInt(String k){return ((Number)data.getOrDefault(k,0)).intValue();}public void putLong(String k,long v){data.put(k,v);}public long getLong(String k){return ((Number)data.getOrDefault(k,0L)).longValue();}}
 public static class Model extends Checks.Model {public int unconsciousTicks,rescues;public String reason;public boolean allowGiveUp;public Model(){for(int i=0;i<8;i++)add(new Checks.Part(0));}public void setUnconsciousState(int ticks,boolean giveUp,boolean causesDeath,String key){this.unconsciousTicks=ticks;allowGiveUp=giveUp;reason=key;}public void clearUnconsciousState(){unconsciousTicks=0;}public void clearUnconsciousPenalties(Object p){}public void scheduleResync(){}public boolean isUnconscious(){return criticalConditionActive;}public int getUnconsciousTicks(){return unconsciousTicks;}public boolean rescueFromCriticalState(Object p,Object healer,boolean delay){if(!Assist.allowed(this))return false;rescues++;criticalConditionActive=false;return true;}public void syncVanillaHealth(Object p){} }
 public static class Event {Player p,t;boolean canceled;Event(Player p,Player t){this.p=p;this.t=t;}public Player getEntity(){return p;}public Player getTarget(){return t;}public void setCanceled(boolean b){canceled=b;}}
 public static class Source {Object attacker;Source(Object a){attacker=a;}public Object getEntity(){return attacker;}public Object getDirectEntity(){return attacker;}}
 public static void main(String[] args){Player victim=new Player(),rescuer=new Player();Model m=new Model(),healthy=new Model();for(Checks.Part part:healthy)part.currentHealth=4;victim.model=m;rescuer.model=healthy;rescuer.world=victim.world;Revival.post(m,victim,null);check(Revival.active(m)&&m.unconsciousTicks==2000&&!m.allowGiveUp);check(!ZeroParts.dead(m,victim)&&ZeroParts.health(m,victim)==1);Revival.post(m,victim,null);check(m.unconsciousTicks==2000);m.get(0).currentHealth=1;check(Revival.active(m));m.get(0).currentHealth=0;check(!Assist.allowed(m));check(Revival.preventDeath(healthy,rescuer,null));Event interaction=new Event(rescuer,victim);check(Assist.interact(interaction)&&interaction.canceled);rescuer.world.clock=159;Assist.tick(new Event(rescuer,null));check(m.rescues==0&&Revival.active(m));rescuer.world.clock=160;Assist.tick(new Event(rescuer,null));check(m.rescues==1&&!Revival.active(m));check(Math.abs(ZeroParts.rawHealth(m,victim)-6)<.0001);check(Assist.bleedingGrace(victim));victim.world.clock=560;check(!Assist.bleedingGrace(victim));for(Checks.Part p:m)p.currentHealth=0;Revival.post(m,victim,null);Event next=new Event(rescuer,victim);Assist.interact(next);rescuer.distance=10;Assist.tick(new Event(rescuer,null));check(!Assist.attempts.containsKey(rescuer)&&m.rescues==1);check(Assist.damage(victim,new Source(null),1)==Boolean.FALSE&&victim.tag.getInt("FAFinishHits")==0);Assist.damage(victim,new Source(rescuer),1);Assist.damage(victim,new Source(rescuer),1);check(victim.alive&&Revival.active(m));Assist.damage(victim,new Source(rescuer),1);check(!victim.alive&&!Revival.active(m));Player client=new Player();client.world.client=true;Model cm=new Model();client.model=cm;Revival.post(cm,client,null);check(!Revival.active(cm));Player alone=new Player();Model am=new Model();alone.model=am;Revival.post(am,alone,null);Assist.self(alone);check(!Assist.attempts.containsKey(alone));alone.main.defib=true;Assist.self(alone);check(Assist.attempts.containsKey(alone));alone.world.clock=159;Assist.tick(new Event(alone,null));check(am.rescues==0&&alone.main.uses==0);alone.world.clock=160;Assist.tick(new Event(alone,null));check(am.rescues==1&&alone.main.uses==1);Assist.hearts(alone);Assist.hearts(alone);check(alone.attribute.values.size()==1);check(((net.minecraft.world.entity.ai.attributes.AttributeModifier)alone.attribute.values.values().iterator().next()).amount()==6);check(alone.world.sounds==2);Player timed=new Player();Model tm=new Model();timed.model=tm;Revival.post(tm,timed,null);timed.world.clock=20;Revival.clock(tm,timed);check(tm.unconsciousTicks==1980);check(Revival.nativeCountdown(1979,tm)==1980);timed.world.clock=1999;Revival.clock(tm,timed);check(timed.alive&&tm.unconsciousTicks==1);timed.world.clock=2000;Revival.clock(tm,timed);check(!timed.alive&&!Revival.active(tm));check(Revival.nativeCountdown(99,new Model())==99);Player imported=new Player();Model im=new Model();imported.model=im;im.criticalConditionActive=true;im.unconsciousTicks=1500;imported.world.clock=5000;Revival.clock(im,imported);check(im.unconsciousTicks==1500);imported.world.clock=5020;Revival.clock(im,imported);check(im.unconsciousTicks==1480);check(Revival.countdown(im,0).toString().contains("firstaid.gui.assist_time_left"));check(Revival.countdown(new Model(),0).toString().contains("firstaid.gui.unconscious_left"));System.out.println("Passed "+n+" downing, rescue timing, restored health, grace, interruption and finishing checks (API doubles)");}
}
